const now = new Date('2026-04-25T10:00:00Z');
const ts = (offsetMs: number) => new Date(now.getTime() + offsetMs).toISOString();

function mkMirrorEval(override?: Partial<MirrorEvalScore>): MirrorEvalScore {
  return {
    groundedness: 0.91,
    evidenceCoverage: 0.87,
    policyCompliance: 0.98,
    unsafeAutonomyRisk: 0.05,
    hallucinationRisk: 0.04,
    businessImpactClarity: 0.89,
    actionSpecificity: 0.88,
    verificationReadiness: 0.92,
    staleContextRisk: 0.08,
    approvalCorrectness: 0.99,
    overallScore: 0.90,
    disposition: 'pass',
    warnings: [],
    runAt: ts(-60_000),
    ...override,
  };
}

function mkApproval(role: string, name: string, approved = true): ApprovalRecord {
  return {
    id: `apr-${role.toLowerCase().replace(/\s/g, '-')}`,
    requestedAt: ts(-1800_000),
    approvedAt: approved ? ts(-900_000) : null,
    approverRole: role,
    approverName: name,
    decision: approved ? 'approved' : 'pending',
    note: approved ? 'Reviewed and approved with full evidence context.' : '',
  };
}

function mkVerification(workcellId: string): VerificationResult {
  return {
    passed: true,
    checkedAt: ts(-300_000),
    checks: [
      { name: 'Expected outcome reached', passed: true, detail: 'System state matches predicted outcome.' },
      { name: 'No unintended side effects', passed: true, detail: 'Adjacent systems unchanged.' },
      { name: 'Audit trail complete', passed: true, detail: 'All tool calls logged to Execution Trace.' },
      { name: 'Evidence coverage ≥ 80%', passed: true, detail: 'Evidence coverage: 91%.' },
    ],
    verifiedBy: 'verification',
  };
}

function mkTrace(workcellId: string, steps: Partial<TraceStep>[]): ExecutionTrace {
  const fullSteps: TraceStep[] = steps.map((s, i) => ({
    id: `step-${i + 1}`,
    type: 'agent_call',
    label: `Step ${i + 1}`,
    startedAt: ts(-3600_000 + i * 120_000),
    completedAt: ts(-3600_000 + i * 120_000 + 90_000),
    latencyMs: 90_000,
    tokens: 1200,
    costUsd: 0.018,
    status: 'success',
    detail: 'Completed successfully.',
    evidenceRefs: [],
    ...s,
  }));
  return {
    id: `trace-${workcellId}`,
    workcellId,
    steps: fullSteps,
    totalTokens: fullSteps.reduce((s, t) => s + (t.tokens ?? 0), 0),
    totalCostUsd: fullSteps.reduce((s, t) => s + (t.costUsd ?? 0), 0),
    totalLatencyMs: fullSteps.reduce((s, t) => s + t.latencyMs, 0),
    startedAt: ts(-3600_000),
    completedAt: ts(-300_000),
  };
}

function mkProof(workcellId: string, title: string): ProofPacket {
  return {
    id: `proof-${workcellId}`,
    workcellId,
    title,
    executionSummary: 'All planned actions executed, verified, and recorded in the Proof Ledger.',
    agentTrace: [
      { operatorId: 'connector', operatorName: 'Connector Operator', startedAt: ts(-3600_000), completedAt: ts(-3480_000), inputTokens: 800, outputTokens: 400, costUsd: 0.018, latencyMs: 120_000, success: true, output: 'Context retrieved and sanitized.' },
      { operatorId: 'analyst', operatorName: 'Analyst Operator', startedAt: ts(-3480_000), completedAt: ts(-3300_000), inputTokens: 2400, outputTokens: 1200, costUsd: 0.054, latencyMs: 180_000, success: true, output: 'Context pack built with 6 citations.' },
      { operatorId: 'risk', operatorName: 'Risk Operator', startedAt: ts(-3300_000), completedAt: ts(-3180_000), inputTokens: 1600, outputTokens: 800, costUsd: 0.036, latencyMs: 120_000, success: true, output: 'Risk classified: workflow_update — approval required.' },
      { operatorId: 'action', operatorName: 'Action Operator', startedAt: ts(-900_000), completedAt: ts(-600_000), inputTokens: 1200, outputTokens: 600, costUsd: 0.027, latencyMs: 300_000, success: true, output: 'Tools executed within approved parameters.' },
      { operatorId: 'verification', operatorName: 'Verification Operator', startedAt: ts(-600_000), completedAt: ts(-480_000), inputTokens: 800, outputTokens: 400, costUsd: 0.018, latencyMs: 120_000, success: true, output: 'All verification checks passed.' },
      { operatorId: 'proof', operatorName: 'Proof Operator', startedAt: ts(-480_000), completedAt: ts(-360_000), inputTokens: 600, outputTokens: 1800, costUsd: 0.036, latencyMs: 120_000, success: true, output: 'Proof Packet assembled and ledger written.' },
    ],
    toolCalls: [
      { toolId: 'context_pack_builder', toolName: 'Context Pack Builder', risk: 'read_only', approvalRequired: false, approvalStatus: 'not_required', calledAt: ts(-3540_000), latencyMs: 45_000, result: { success: true }, auditRef: `audit-${workcellId}-1` },
      { toolId: 'signal_reader', toolName: 'Signal Reader', risk: 'read_only', approvalRequired: false, approvalStatus: 'not_required', calledAt: ts(-3480_000), latencyMs: 12_000, result: { signalCount: 5 }, auditRef: `audit-${workcellId}-2` },
      { toolId: 'covenant_guard', toolName: 'Covenant Guard', risk: 'read_only', approvalRequired: false, approvalStatus: 'not_required', calledAt: ts(-3300_000), latencyMs: 8_000, result: { approvalRequired: true }, auditRef: `audit-${workcellId}-3` },
      { toolId: 'revops_writer', toolName: 'RevOps System Writer', risk: 'high', approvalRequired: true, approvalStatus: 'approved', calledAt: ts(-900_000), latencyMs: 32_000, result: { success: true }, auditRef: `audit-${workcellId}-4` },
      { toolId: 'proof_ledger_writer', toolName: 'Proof Ledger Writer', risk: 'low', approvalRequired: false, approvalStatus: 'not_required', calledAt: ts(-480_000), latencyMs: 5_000, result: { written: true }, auditRef: `audit-${workcellId}-5` },
    ],
    approvalChain: [mkApproval('VP Revenue', 'Sarah Chen')],
    verificationResult: mkVerification(workcellId),
    evidenceCoverage: 0.91,
    provenAt: ts(-360_000),
    hashDigest: `sha3-a11oy-${workcellId.slice(-8).replace('-', '')}f2c1`,
  };
}

function mkContext(workcellId: string, citations: Array<{ label: string; source: string; content: string }>): ContextPack {
  return {
    id: `ctx-${workcellId}`,
    workcellId,
    mode: 'balanced',
    citations: citations.map((c, i) => ({
      id: `cite-${i + 1}`,
      label: c.label,
      source: c.source,
      capturedAt: ts(-7200_000 + i * 600_000),
      freshnessScore: 0.85 - i * 0.04,
      isStale: i > 3,
      content: c.content,
      confidence: 0.92 - i * 0.02,
      redacted: false,
    })),
    tokenBudget: 8000,
    tokensUsed: 3200 + citations.length * 400,
    buildAt: ts(-3600_000),
    staleCount: citations.filter((_, i) => i > 3).length,
    redactedCount: 0,
  };
}

